class Solution { public: int minimizeTheDifference(vector<vector<int>>& mat,int target){int maximum=0;for(auto& row:mat)maximum+=*max_element(row.begin(),row.end());vector<bool> reachable(maximum+1);reachable[0]=true;int limit=0;for(auto& row:mat){vector<bool> next(maximum+1);for(int sum=0;sum<=limit;++sum)if(reachable[sum])for(int value:row)next[sum+value]=true;limit+=*max_element(row.begin(),row.end());reachable.swap(next);}int answer=INT_MAX;for(int sum=0;sum<=maximum;++sum)if(reachable[sum])answer=min(answer,abs(sum-target));return answer;} };
